    "body": "import java.util.Optional;\n\npublic class Tests {\n    static void check(boolean condition, String name) {\n        if (!condition) throw new AssertionError(\"FAIL: \" + name);\n        System.out.println(\"PASS: \" + name);\n    }\n\n    public static void main(String[] args) throws Exception {\n        Cache<Integer, String> c = new LRUCache<>(2);\n        check(c.get(1).isEmpty(), \"miss on empty cache returns empty\");\n\n        c.put(1, \"one\");\n        c.put(2, \"two\");\n        c.get(1);\n        c.put(3, \"three\");\n        check(c.get(2).isEmpty() && c.get(1).isPresent() && c.get(3).isPresent(), \"evicts least recently used, not oldest inserted\");\n\n        c = new LRUCache<>(2);\n        c.put(1, \"one\");\n        c.put(2, \"two\");\n        c.put(1, \"uno\");\n        check(c.size() == 2 && c.get(1).get().equals(\"uno\") && c.get(2).isPresent(), \"updating an existing key does not evict\");\n\n        c = new LRUCache<>(2);\n        c.put(1, \"one\");\n        c.put(2, \"two\");\n        c.put(1, \"uno\"); // refreshes 1, so 2 is now LRU\n        c.put(3, \"three\");\n        check(c.get(2).isEmpty(), \"put on existing key refreshes recency\");\n\n        c = new LRUCache<>(1);\n        c.put(1, \"one\");\n        c.put(2, \"two\");\n        check(c.get(1).isEmpty() && c.get(2).get().equals(\"two\") && c.size() == 1, \"capacity 1 keeps only latest key\");\n\n        boolean threw = false;\n        try { new LRUCache<Integer, Integer>(0); } catch (IllegalArgumentException e) { threw = true; }\n        check(threw, \"non-positive capacity rejected\");\n\n        Cache<Integer, Integer> lfu = new PolicyCache<>(2, new LfuPolicy<>());\n        lfu.put(1, 1);\n        lfu.put(2, 2);\n        lfu.get(1);\n        lfu.put(3, 3);\n        check(lfu.get(2).isEmpty() && lfu.get(1).isPresent(), \"LFU evicts the least frequently used key\");\n\n        Cache<Integer, Integer> lfuTie = new PolicyCache<>(2, new LfuPolicy<>());\n        lfuTie.put(1, 1);\n        lfuTie.put(2, 2);\n        lfuTie.put(3, 3);\n        check(lfuTie.get(1).isEmpty(), \"LFU breaks frequency ties by evicting the older key\");\n\n        Cache<Integer, Integer> fifo = new PolicyCache<>(2, new FifoPolicy<>());\n        fifo.put(1, 1);\n        fifo.put(2, 2);\n        fifo.get(1);\n        fifo.put(3, 3);\n        check(fifo.get(1).isEmpty(), \"FIFO ignores reads when choosing a victim\");\n\n        Cache<Integer, Integer> lruViaPolicy = new PolicyCache<>(2, new LruPolicy<>());\n        lruViaPolicy.put(1, 1);\n        lruViaPolicy.put(2, 2);\n        lruViaPolicy.get(1);\n        lruViaPolicy.put(3, 3);\n        check(lruViaPolicy.get(2).isEmpty() && lruViaPolicy.get(1).isPresent(), \"LruPolicy behaves like LRUCache\");\n\n        Cache<Integer, Integer> shared = new SynchronizedCache<>(new LRUCache<>(50));\n        Thread[] ts = new Thread[8];\n        for (int t = 0; t < ts.length; t++) {\n            ts[t] = new Thread(() -> {\n                for (int i = 0; i < 50000; i++) {\n                    shared.put(i % 200, i);\n                    shared.get((i * 7) % 200);\n                }\n            });\n            ts[t].start();\n        }\n        for (Thread t : ts) t.join();\n        check(shared.size() <= 50, \"concurrent use never exceeds capacity\");\n    }\n}\n",
