      "file": "TaskService.java",
      "body": "import java.time.LocalDate;\nimport java.util.Comparator;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.NoSuchElementException;\nimport java.util.concurrent.CopyOnWriteArrayList;\nimport java.util.stream.Collectors;\n\npublic class TaskService {\n    private final Map<Long, Task> tasks = new LinkedHashMap<>();\n    private final List<TaskListener> listeners = new CopyOnWriteArrayList<>();\n    private long nextId = 1;\n\n    public void addListener(TaskListener listener) {\n        listeners.add(listener);\n    }\n\n    public synchronized Task createTask(String title, String description, Priority priority, LocalDate dueDate) {\n        Task task = new Task(nextId++, title, description, priority, dueDate);\n        tasks.put(task.id(), task);\n        return task;\n    }\n\n    public synchronized void assign(long taskId, User user) {\n        Task task = find(taskId);\n        task.assignTo(user); // reassigning simply replaces the single assignee\n        listeners.forEach(l -> l.onAssigned(task, user));\n    }\n\n    public synchronized void updateStatus(long taskId, TaskStatus next) {\n        Task task = find(taskId);\n        TaskStatus previous = task.status();\n        task.moveTo(next); // throws InvalidTransitionException, leaving the task unchanged\n        listeners.forEach(l -> l.onStatusChanged(task, previous, next));\n    }\n\n    public synchronized List<Task> search(TaskFilter filter, Comparator<Task> order) {\n        return tasks.values().stream().filter(filter::test).sorted(order).collect(Collectors.toList());\n    }\n\n    public synchronized List<Task> search(TaskFilter filter) {\n        return search(filter, Comparator.comparingLong(Task::id));\n    }\n\n    private Task find(long id) {\n        Task task = tasks.get(id);\n        if (task == null) throw new NoSuchElementException(\"No task with id \" + id);\n        return task;\n    }\n}\n"
