    "body": "import java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.NoSuchElementException;\nimport java.util.stream.Collectors;\n\npublic class Tests {\n    static void check(boolean condition, String name) {\n        if (!condition) throw new AssertionError(\"FAIL: \" + name);\n        System.out.println(\"PASS: \" + name);\n    }\n\n    static List<Long> ids(List<Task> tasks) {\n        return tasks.stream().map(Task::id).collect(Collectors.toList());\n    }\n\n    public static void main(String[] args) {\n        TaskService s = new TaskService();\n        User a = new User(\"a\", \"Asha\");\n        User b = new User(\"b\", \"Ben\");\n        Task t1 = s.createTask(\"one\", \"\", Priority.LOW, LocalDate.of(2026, 1, 3));\n        Task t2 = s.createTask(\"two\", \"\", Priority.HIGH, LocalDate.of(2026, 1, 1));\n        Task t3 = s.createTask(\"three\", \"\", Priority.MEDIUM, null);\n\n        check(t1.status() == TaskStatus.TODO && t1.assignee().isEmpty(), \"new task is TODO and unassigned\");\n\n        boolean blank = false;\n        try { s.createTask(\" \", \"\", Priority.LOW, null); } catch (IllegalArgumentException e) { blank = true; }\n        check(blank, \"blank title rejected\");\n\n        s.assign(t1.id(), a);\n        s.assign(t1.id(), b);\n        check(t1.assignee().get() == b, \"reassigning replaces the single assignee\");\n\n        boolean missing = false;\n        try { s.assign(999, a); } catch (NoSuchElementException e) { missing = true; }\n        check(missing, \"unknown task id rejected\");\n\n        s.updateStatus(t1.id(), TaskStatus.IN_PROGRESS);\n        s.updateStatus(t1.id(), TaskStatus.IN_REVIEW);\n        s.updateStatus(t1.id(), TaskStatus.DONE);\n        check(t1.status() == TaskStatus.DONE, \"full happy-path lifecycle\");\n\n        boolean skip = false;\n        try { s.updateStatus(t2.id(), TaskStatus.DONE); } catch (InvalidTransitionException e) { skip = true; }\n        check(skip && t2.status() == TaskStatus.TODO, \"skipping a state is rejected and leaves the task unchanged\");\n\n        boolean terminal = false;\n        try { s.updateStatus(t1.id(), TaskStatus.IN_PROGRESS); } catch (InvalidTransitionException e) { terminal = true; }\n        check(terminal, \"DONE is terminal\");\n\n        s.assign(t2.id(), a);\n        s.assign(t3.id(), a);\n        check(ids(s.search(TaskFilter.byAssignee(a))).equals(List.of(2L, 3L)), \"filter by assignee\");\n        check(ids(s.search(TaskFilter.byStatus(TaskStatus.DONE))).equals(List.of(1L)), \"filter by status\");\n        check(ids(s.search(TaskFilter.byPriority(Priority.HIGH).and(TaskFilter.byAssignee(a)))).equals(List.of(2L)), \"AND of two filters\");\n        check(ids(s.search(TaskFilter.byPriority(Priority.HIGH).or(TaskFilter.byPriority(Priority.LOW)))).equals(List.of(1L, 2L)), \"OR of two filters\");\n        check(ids(s.search(TaskFilter.dueOnOrBefore(LocalDate.of(2026, 1, 2)))).equals(List.of(2L)), \"due-date filter ignores tasks with no due date\");\n        check(ids(s.search(TaskFilter.any(), TaskSort.byPriority())).equals(List.of(2L, 3L, 1L)), \"sort by priority, HIGH first\");\n        check(ids(s.search(TaskFilter.any(), TaskSort.byDueDate())).equals(List.of(2L, 1L, 3L)), \"sort by due date, undated last\");\n\n        // Extensibility: a brand-new criterion needs no change to TaskService.\n        TaskFilter titleHasT = t -> t.title().startsWith(\"t\");\n        check(ids(s.search(titleHasT)).equals(List.of(2L, 3L)), \"custom filter lambda works without touching the service\");\n\n        EmailNotifier email = new EmailNotifier();\n        TaskService s2 = new TaskService();\n        s2.addListener(email);\n        Task x = s2.createTask(\"x\", \"\", Priority.LOW, null);\n        s2.updateStatus(x.id(), TaskStatus.IN_PROGRESS);\n        check(email.sent().isEmpty(), \"no notification when nobody is assigned\");\n        s2.assign(x.id(), a);\n        s2.updateStatus(x.id(), TaskStatus.IN_REVIEW);\n        check(email.sent().size() == 2, \"assignee notified on assignment and on status change\");\n\n        List<String> events = new ArrayList<>();\n        s2.addListener(new TaskListener() {\n            public void onAssigned(Task t, User u) { events.add(\"assigned\"); }\n            public void onStatusChanged(Task t, TaskStatus f, TaskStatus to) { events.add(\"status\"); }\n        });\n        s2.assign(x.id(), b);\n        check(events.equals(List.of(\"assigned\")), \"a second listener channel can be plugged in\");\n    }\n}\n",
    "output": "PASS: new task is TODO and unassigned\nPASS: blank title rejected\nPASS: reassigning replaces the single assignee\nPASS: unknown task id rejected\nPASS: full happy-path lifecycle\nPASS: skipping a state is rejected and leaves the task unchanged\nPASS: DONE is terminal\nPASS: filter by assignee\nPASS: filter by status\nPASS: AND of two filters\nPASS: OR of two filters\nPASS: due-date filter ignores tasks with no due date\nPASS: sort by priority, HIGH first\nPASS: sort by due date, undated last\nPASS: custom filter lambda works without touching the service\nPASS: no notification when nobody is assigned\n  [email to Asha: You were assigned: x]\n  [email to Asha: 'x' moved IN_PROGRESS -> IN_REVIEW]\nPASS: assignee notified on assignment and on status change\n  [email to Ben: You were assigned: x]\nPASS: a second listener channel can be plugged in\n"
