    "body": "import java.util.ArrayList;\nimport java.util.EnumMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.concurrent.CompletableFuture;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        Map<Ingredient, Integer> stock = new EnumMap<>(Ingredient.class);\n        stock.put(Ingredient.WATER, 2000);\n        stock.put(Ingredient.MILK, 750);\n        stock.put(Ingredient.COFFEE_BEANS, 200);\n        stock.put(Ingredient.TEA_LEAVES, 100);\n        stock.put(Ingredient.SUGAR, 100);\n        CoffeeMachine machine = new CoffeeMachine(3, new Inventory(stock), new TimedBrewer(30));\n\n        System.out.println(\"--- Requirement 1: menu is data ---\");\n        Beverage latte = new BasicBeverage(\"Latte\", 120, Recipe.of(Ingredient.WATER, 100).and(Ingredient.MILK, 150).and(Ingredient.COFFEE_BEANS, 20));\n        Beverage espresso = new BasicBeverage(\"Espresso\", 80, Recipe.of(Ingredient.WATER, 50).and(Ingredient.COFFEE_BEANS, 20));\n        machine.addBeverage(latte);\n        machine.addBeverage(espresso);\n        machine.addBeverage(new BasicBeverage(\"Tea\", 50, Recipe.of(Ingredient.WATER, 150).and(Ingredient.TEA_LEAVES, 10))); // new drink: no code change\n        System.out.println(\"Latte recipe: \" + latte.recipe());\n\n        System.out.println(\"--- Requirement 2: serve, with an add-on ---\");\n        AddOn extraShot = new AddOn(\"Extra shot\", 30, Recipe.of(Ingredient.COFFEE_BEANS, 20));\n        AddOn extraSugar = new AddOn(\"Extra sugar\", 10, Recipe.of(Ingredient.SUGAR, 5));\n        System.out.println(machine.order(\"Espresso\", new CashPayment(100)).get());\n        System.out.println(machine.order(\"Latte\", List.of(extraShot, extraSugar), new CardPayment(\"4242\", 500)).get());\n        System.out.println(machine.order(\"Mocha\", new CashPayment(100)).get());\n\n        System.out.println(\"--- Payment declined: ingredients are returned ---\");\n        int before = machine.inventory().level(Ingredient.MILK);\n        System.out.println(machine.order(\"Latte\", new CardPayment(\"0000\", 10)).get());\n        System.out.println(\"milk before = \" + before + \", after = \" + machine.inventory().level(Ingredient.MILK));\n\n        System.out.println(\"--- Requirement 3: 10 concurrent latte orders, milk left for only 3 ---\");\n        machine.inventory().refill(Ingredient.WATER, 1000);\n        // The operator drains the milk tank down to exactly three lattes' worth (3 x 150).\n        machine.inventory().tryConsume(Recipe.of(Ingredient.MILK, machine.inventory().level(Ingredient.MILK) - 450));\n        List<CompletableFuture<OrderResult>> futures = new ArrayList<>();\n        for (int i = 0; i < 10; i++) futures.add(machine.order(\"Latte\", new CashPayment(200)));\n        long served = 0;\n        long refused = 0;\n        for (CompletableFuture<OrderResult> f : futures) {\n            if (f.get().isServed()) served++; else refused++;\n        }\n        System.out.println(\"served = \" + served + \", refused = \" + refused);\n        System.out.println(\"milk now = \" + machine.inventory().level(Ingredient.MILK));\n\n        System.out.println(\"--- Requirement 4: operator view and refill ---\");\n        System.out.println(\"low stock (<= 60): \" + machine.inventory().lowStock(60));\n        machine.inventory().refill(Ingredient.MILK, 500);\n        System.out.println(\"after refill, milk = \" + machine.inventory().level(Ingredient.MILK));\n        machine.shutdown();\n    }\n}\n",
