    "body": "import java.util.EnumMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.concurrent.CompletableFuture;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Tests {\n    static void check(boolean condition, String name) {\n        if (!condition) throw new AssertionError(\"FAIL: \" + name);\n        System.out.println(\"PASS: \" + name);\n    }\n\n    static Inventory stock(int water, int milk, int beans) {\n        Map<Ingredient, Integer> m = new EnumMap<>(Ingredient.class);\n        m.put(Ingredient.WATER, water);\n        m.put(Ingredient.MILK, milk);\n        m.put(Ingredient.COFFEE_BEANS, beans);\n        return new Inventory(m);\n    }\n\n    static final Beverage LATTE = new BasicBeverage(\"Latte\", 120,\n        Recipe.of(Ingredient.WATER, 100).and(Ingredient.MILK, 150).and(Ingredient.COFFEE_BEANS, 20));\n\n    public static void main(String[] args) throws Exception {\n        // Atomic all-or-nothing consumption.\n        Inventory inv = stock(1000, 100, 100); // not enough milk for a latte\n        Optional<Ingredient> missing = inv.tryConsume(LATTE.recipe());\n        check(missing.equals(Optional.of(Ingredient.MILK)), \"reports the missing ingredient\");\n        check(inv.level(Ingredient.WATER) == 1000 && inv.level(Ingredient.COFFEE_BEANS) == 100,\n            \"failed consume leaves every other ingredient untouched\");\n\n        // Add-on composition.\n        AddOn shot = new AddOn(\"Extra shot\", 30, Recipe.of(Ingredient.COFFEE_BEANS, 20));\n        Beverage custom = new CustomizedBeverage(LATTE, List.of(shot, shot));\n        check(custom.price() == 180 && custom.recipe().amounts().get(Ingredient.COFFEE_BEANS) == 60,\n            \"add-ons stack onto price and recipe\");\n        check(custom.name().equals(\"Latte + Extra shot + Extra shot\"), \"add-ons appear in the name\");\n\n        // Machine behaviour.\n        CoffeeMachine machine = new CoffeeMachine(2, stock(1000, 450, 1000), new TimedBrewer(5));\n        machine.addBeverage(LATTE);\n        check(machine.order(\"Nope\", new CashPayment(999)).get().status() == OrderResult.Status.UNKNOWN_BEVERAGE,\n            \"unknown beverage rejected\");\n        OrderResult declined = machine.order(\"Latte\", new CashPayment(10)).get();\n        check(declined.status() == OrderResult.Status.PAYMENT_DECLINED\n            && machine.inventory().level(Ingredient.MILK) == 450, \"declined payment restores ingredients\");\n        check(machine.order(\"Latte\", new CardPayment(\"1\", 120)).get().isServed()\n            && machine.inventory().level(Ingredient.MILK) == 300, \"card payment serves and deducts\");\n\n        // Concurrency: milk for exactly 3 lattes (450 total is already 300 now: 2 left; refill to 450 -> 3).\n        machine.inventory().refill(Ingredient.MILK, 150); // 450 = exactly three lattes\n        CompletableFuture<?>[] fs = new CompletableFuture<?>[12];\n        AtomicInteger served = new AtomicInteger();\n        for (int i = 0; i < fs.length; i++) {\n            fs[i] = machine.order(\"Latte\", new CashPayment(500)).thenAccept(r -> { if (r.isServed()) served.incrementAndGet(); });\n        }\n        CompletableFuture.allOf(fs).get();\n        check(served.get() == 3, \"12 simultaneous orders, stock for 3: exactly 3 served\");\n        check(machine.inventory().level(Ingredient.MILK) == 0, \"stock is exactly zero, never negative\");\n\n        // Refill and low-stock reporting.\n        check(machine.inventory().lowStock(10).containsKey(Ingredient.MILK), \"low-stock report includes empty ingredient\");\n        machine.inventory().refill(Ingredient.MILK, 150);\n        check(machine.order(\"Latte\", new CashPayment(500)).get().isServed(), \"serves again after refill\");\n        machine.shutdown();\n\n        // Outlet limit: with 2 outlets, never more than 2 drinks brewing at once, and 2 do overlap.\n        AtomicInteger running = new AtomicInteger();\n        AtomicInteger peak = new AtomicInteger();\n        Brewer probe = b -> {\n            int now = running.incrementAndGet();\n            peak.accumulateAndGet(now, Math::max);\n            Thread.sleep(50);\n            running.decrementAndGet();\n        };\n        CoffeeMachine two = new CoffeeMachine(2, stock(10000, 10000, 10000), probe);\n        two.addBeverage(LATTE);\n        CompletableFuture<?>[] batch = new CompletableFuture<?>[8];\n        for (int i = 0; i < batch.length; i++) batch[i] = two.order(\"Latte\", new CashPayment(500));\n        CompletableFuture.allOf(batch).get();\n        check(peak.get() == 2, \"outlets brew in parallel but never exceed the outlet count\");\n        two.shutdown();\n\n        // Extensibility: a new beverage and a new payment method need no machine changes.\n        CoffeeMachine m3 = new CoffeeMachine(1, stock(1000, 1000, 1000), new TimedBrewer(1));\n        m3.addBeverage(new BasicBeverage(\"Americano\", 60, Recipe.of(Ingredient.WATER, 200).and(Ingredient.COFFEE_BEANS, 15)));\n        PaymentStrategy wallet = new PaymentStrategy() {\n            public boolean charge(int amount) { return true; }\n            public String description() { return \"wallet\"; }\n        };\n        check(m3.order(\"Americano\", wallet).get().isServed(), \"new beverage and new payment method plug in\");\n        m3.shutdown();\n    }\n}\n",
