      "file": "InMemoryBank.java",
      "body": "import java.util.HashMap;\nimport java.util.HashSet;\nimport java.util.Map;\nimport java.util.Set;\n\npublic class InMemoryBank implements BankService {\n    private static final int MAX_ATTEMPTS = 3;\n\n    private final Map<String, String> pins = new HashMap<>();      // account -> pin (demo only; never store raw PINs)\n    private final Map<String, Long> balances = new HashMap<>();\n    private final Map<String, Integer> failures = new HashMap<>(); // card number -> consecutive wrong PINs\n    private final Set<String> blocked = new HashSet<>();\n\n    public void openAccount(String accountId, String pin, long balance) {\n        pins.put(accountId, pin);\n        balances.put(accountId, balance);\n    }\n\n    @Override\n    public synchronized boolean isBlocked(Card card) {\n        return blocked.contains(card.number());\n    }\n\n    @Override\n    public synchronized PinResult validatePin(Card card, String pin) {\n        if (blocked.contains(card.number())) return PinResult.CARD_BLOCKED;\n        if (pin != null && pin.equals(pins.get(card.accountId()))) {\n            failures.remove(card.number());\n            return PinResult.OK;\n        }\n        int count = failures.merge(card.number(), 1, Integer::sum);\n        if (count >= MAX_ATTEMPTS) {\n            blocked.add(card.number());\n            return PinResult.CARD_BLOCKED;\n        }\n        return PinResult.WRONG_PIN;\n    }\n\n    @Override\n    public synchronized long balance(String accountId) {\n        return balances.get(accountId);\n    }\n\n    @Override\n    public synchronized boolean debit(String accountId, long amount) {\n        long current = balances.get(accountId);\n        if (current < amount) return false;\n        balances.put(accountId, current - amount);\n        return true;\n    }\n\n    @Override\n    public synchronized void credit(String accountId, long amount) {\n        balances.merge(accountId, amount, Long::sum);\n    }\n}\n"
