      "file": "ATMState.java",
      "body": "import java.util.Map;\n\n/** One method per user action. A state overrides only the actions that make sense in it. */\npublic interface ATMState {\n    String name();\n\n    default void insertCard(Card card) {\n        throw new IllegalStateException(\"Cannot insert a card while \" + name());\n    }\n\n    default PinResult enterPin(String pin) {\n        throw new IllegalStateException(\"Cannot enter a PIN while \" + name());\n    }\n\n    default long checkBalance() {\n        throw new IllegalStateException(\"Cannot check balance while \" + name());\n    }\n\n    default Map<Integer, Integer> withdraw(long amount) {\n        throw new IllegalStateException(\"Cannot withdraw while \" + name());\n    }\n\n    default void deposit(long amount) {\n        throw new IllegalStateException(\"Cannot deposit while \" + name());\n    }\n\n    void ejectCard();\n}\n"
