      "body": "import java.util.Map;\n\n/** The context. It holds the current state and the shared collaborators, and delegates every action. */\npublic class ATM {\n    private final BankService bank;\n    private final CashDispenser dispenser;\n    private final ATMState idle = new IdleState(this);\n    private final ATMState cardInserted = new CardInsertedState(this);\n    private final ATMState authenticated = new AuthenticatedState(this);\n    private ATMState state = idle;\n    private Card currentCard;\n\n    public ATM(BankService bank, CashDispenser dispenser) {\n        this.bank = bank;\n        this.dispenser = dispenser;\n    }\n\n    // All public actions are synchronized: one customer session at a time, and state changes are never interleaved.\n    public synchronized void insertCard(Card card) { state.insertCard(card); }\n\n    public synchronized PinResult enterPin(String pin) { return state.enterPin(pin); }\n\n    public synchronized long checkBalance() { return state.checkBalance(); }\n\n    public synchronized Map<Integer, Integer> withdraw(long amount) { return state.withdraw(amount); }\n\n    public synchronized void deposit(long amount) { state.deposit(amount); }\n\n    public synchronized void ejectCard() { state.ejectCard(); }\n\n    public synchronized String stateName() { return state.name(); }\n\n    // Package-private hooks used by the states.\n    BankService bank() { return bank; }\n\n    CashDispenser dispenser() { return dispenser; }\n\n    Card currentCard() { return currentCard; }\n\n    ATMState cardInsertedState() { return cardInserted; }\n\n    ATMState authenticatedState() { return authenticated; }\n\n    void setState(ATMState next) { this.state = next; }\n\n    void startSession(Card card) { this.currentCard = card; }\n\n    void endSession() {\n        this.currentCard = null;\n        this.state = idle;\n    }\n}\n"
