    "body": "import java.util.Map;\nimport java.util.TreeMap;\n\npublic class Main {\n    public static void main(String[] args) {\n        InMemoryBank bank = new InMemoryBank();\n        bank.openAccount(\"acc-1\", \"1234\", 10_000);\n        bank.openAccount(\"acc-2\", \"9999\", 500);\n        Card card = new Card(\"4111-0001\", \"acc-1\");\n        Card other = new Card(\"4111-0002\", \"acc-2\");\n\n        Map<Integer, Integer> notes = new TreeMap<>();\n        notes.put(500, 10);\n        notes.put(200, 10);\n        notes.put(100, 10);\n        CashDispenser dispenser = new CashDispenser(notes);\n        ATM atm = new ATM(bank, dispenser);\n\n        System.out.println(\"--- Requirement 1: card, PIN, session ---\");\n        System.out.println(\"state: \" + atm.stateName());\n        try { atm.withdraw(500); } catch (IllegalStateException e) { System.out.println(\"rejected: \" + e.getMessage()); }\n        atm.insertCard(card);\n        System.out.println(\"state: \" + atm.stateName());\n        try { atm.insertCard(other); } catch (IllegalStateException e) { System.out.println(\"rejected: \" + e.getMessage()); }\n        System.out.println(\"wrong PIN -> \" + atm.enterPin(\"0000\"));\n        System.out.println(\"right PIN -> \" + atm.enterPin(\"1234\"));\n        System.out.println(\"state: \" + atm.stateName());\n\n        System.out.println(\"--- Requirement 2: balance and withdraw ---\");\n        System.out.println(\"balance = \" + atm.checkBalance());\n        System.out.println(\"withdraw 1300 -> \" + atm.withdraw(1300));\n        System.out.println(\"balance = \" + atm.checkBalance());\n        try { atm.withdraw(150); } catch (IllegalArgumentException e) { System.out.println(\"rejected: \" + e.getMessage()); }\n        try { atm.withdraw(50_000); } catch (IllegalStateException e) { System.out.println(\"rejected: \" + e.getMessage()); }\n\n        System.out.println(\"--- Requirement 3: dispensing picks a mix that works ---\");\n        Map<Integer, Integer> scarce = new TreeMap<>();\n        scarce.put(500, 1);\n        scarce.put(200, 3);\n        ATM small = new ATM(bank, new CashDispenser(scarce));\n        small.insertCard(card);\n        small.enterPin(\"1234\");\n        System.out.println(\"withdraw 600 with one 500 and three 200s -> \" + small.withdraw(600));\n        small.ejectCard();\n\n        System.out.println(\"--- Requirement 4: eject ends the session ---\");\n        atm.ejectCard();\n        System.out.println(\"state: \" + atm.stateName());\n\n        System.out.println(\"--- Extensibility: new denomination and deposit ---\");\n        atm.insertCard(card);\n        atm.enterPin(\"1234\");\n        dispenser.load(50, 10); // a new denomination: no change to the dispenser logic\n        System.out.println(\"withdraw 150 after loading 50s -> \" + atm.withdraw(150));\n        atm.deposit(2_000);\n        System.out.println(\"balance after deposit = \" + atm.checkBalance());\n        atm.ejectCard();\n\n        System.out.println(\"--- PIN lockout ---\");\n        atm.insertCard(other);\n        System.out.println(atm.enterPin(\"1\"));\n        System.out.println(atm.enterPin(\"2\"));\n        System.out.println(atm.enterPin(\"3\") + \", state: \" + atm.stateName());\n        try { atm.insertCard(other); } catch (IllegalStateException e) { System.out.println(\"rejected: \" + e.getMessage()); }\n    }\n}\n",
