    "body": "import java.util.Map;\nimport java.util.TreeMap;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Tests {\n    static void check(boolean condition, String name) {\n        if (!condition) throw new AssertionError(\"FAIL: \" + name);\n        System.out.println(\"PASS: \" + name);\n    }\n\n    static <T extends Throwable> boolean throwsOf(Class<T> type, Runnable action) {\n        try { action.run(); } catch (Throwable t) { return type.isInstance(t); }\n        return false;\n    }\n\n    static InMemoryBank bank() {\n        InMemoryBank b = new InMemoryBank();\n        b.openAccount(\"a\", \"1111\", 5_000);\n        b.openAccount(\"b\", \"2222\", 100);\n        return b;\n    }\n\n    static final Card A = new Card(\"c-a\", \"a\");\n    static final Card B = new Card(\"c-b\", \"b\");\n\n    static CashDispenser cash(int... pairs) {\n        Map<Integer, Integer> m = new TreeMap<>();\n        for (int i = 0; i < pairs.length; i += 2) m.put(pairs[i], pairs[i + 1]);\n        return new CashDispenser(m);\n    }\n\n    static ATM loggedIn(InMemoryBank bank, CashDispenser d) {\n        ATM atm = new ATM(bank, d);\n        atm.insertCard(A);\n        atm.enterPin(\"1111\");\n        return atm;\n    }\n\n    public static void main(String[] args) throws Exception {\n        ATM atm = new ATM(bank(), cash(500, 10, 100, 10));\n        check(throwsOf(IllegalStateException.class, () -> atm.withdraw(100)), \"no actions before a card is inserted\");\n        check(throwsOf(IllegalStateException.class, () -> atm.enterPin(\"1111\")), \"cannot enter PIN with no card\");\n\n        atm.insertCard(A);\n        check(throwsOf(IllegalStateException.class, () -> atm.checkBalance()), \"no balance before PIN\");\n        check(throwsOf(IllegalStateException.class, () -> atm.insertCard(B)), \"second customer cannot start a session\");\n        check(atm.enterPin(\"0000\") == PinResult.WRONG_PIN, \"wrong PIN reported\");\n        check(atm.enterPin(\"1111\") == PinResult.OK && atm.checkBalance() == 5_000, \"right PIN authenticates and shows balance\");\n\n        Map<Integer, Integer> got = atm.withdraw(1_200);\n        check(got.equals(Map.of(500, 2, 100, 2)) && atm.checkBalance() == 3_800, \"withdraw dispenses notes and debits account\");\n        check(throwsOf(IllegalArgumentException.class, () -> atm.withdraw(150)), \"amount not a multiple of smallest note rejected\");\n        check(throwsOf(IllegalArgumentException.class, () -> atm.withdraw(-100)), \"negative amount rejected\");\n        atm.ejectCard();\n        check(atm.stateName().equals(\"idle\"), \"eject returns to idle\");\n        check(throwsOf(IllegalStateException.class, () -> atm.withdraw(100)), \"no actions after eject\");\n\n        // Insufficient funds must not consume notes.\n        CashDispenser d = cash(100, 100);\n        ATM poor = new ATM(bank(), d);\n        poor.insertCard(B);\n        poor.enterPin(\"2222\");\n        long before = d.totalCash();\n        check(throwsOf(IllegalStateException.class, () -> poor.withdraw(500)), \"insufficient funds rejected\");\n        check(d.totalCash() == before && poor.checkBalance() == 100, \"failed withdrawal leaves cash and balance unchanged\");\n\n        // Machine cannot make the amount.\n        CashDispenser tiny = cash(500, 1, 100, 1);\n        ATM tinyAtm = loggedIn(bank(), tiny);\n        check(throwsOf(IllegalStateException.class, () -> tinyAtm.withdraw(1_000)), \"refuses when ATM lacks the notes\");\n        check(tiny.totalCash() == 600 && tinyAtm.checkBalance() == 5_000, \"refusal changes nothing\");\n\n        // Greedy dead end: 600 from one 500 and three 200s needs 3x200.\n        CashDispenser scarce = cash(500, 1, 200, 3);\n        ATM scarceAtm = loggedIn(bank(), scarce);\n        check(scarceAtm.withdraw(600).equals(Map.of(200, 3)), \"backtracks past a greedy dead end (3 x 200, not 500 + ?)\");\n\n        // Extensibility: new denomination.\n        CashDispenser grow = cash(500, 1);\n        grow.load(100, 5);\n        ATM growAtm = loggedIn(bank(), grow);\n        check(growAtm.withdraw(700).equals(Map.of(500, 1, 100, 2)), \"newly loaded denomination is used without code changes\");\n\n        // New operation: deposit.\n        ATM dep = loggedIn(bank(), cash(100, 1));\n        dep.deposit(250);\n        check(dep.checkBalance() == 5_250, \"deposit credits the account\");\n        check(throwsOf(IllegalArgumentException.class, () -> dep.deposit(0)), \"non-positive deposit rejected\");\n\n        // PIN lockout.\n        InMemoryBank lockBank = bank();\n        ATM lock = new ATM(lockBank, cash(100, 1));\n        lock.insertCard(B);\n        PinResult r1 = lock.enterPin(\"x\");\n        PinResult r2 = lock.enterPin(\"y\");\n        PinResult r3 = lock.enterPin(\"z\");\n        check(r1 == PinResult.WRONG_PIN && r2 == PinResult.WRONG_PIN && r3 == PinResult.CARD_BLOCKED, \"three wrong PINs block the card\");\n        check(lock.stateName().equals(\"idle\"), \"blocked card ends the session\");\n        check(throwsOf(IllegalStateException.class, () -> lock.insertCard(B)), \"blocked card cannot start a new session\");\n\n        // Concurrency: many threads fight for one ATM; every attempt either gets a full session or is rejected.\n        CashDispenser shared = cash(100, 1000);\n        InMemoryBank sharedBank = bank();\n        sharedBank.openAccount(\"rich\", \"0\", 1_000_000);\n        Card rich = new Card(\"c-r\", \"rich\");\n        ATM busy = new ATM(sharedBank, shared);\n        AtomicInteger sessions = new AtomicInteger();\n        AtomicInteger rejected = new AtomicInteger();\n        Thread[] ts = new Thread[8];\n        for (int t = 0; t < ts.length; t++) {\n            ts[t] = new Thread(() -> {\n                for (int i = 0; i < 200; i++) {\n                    try {\n                        busy.insertCard(rich);\n                        // Another thread may eject our session between calls; any failure here is a clean rejection.\n                        busy.enterPin(\"0\");\n                        busy.withdraw(100);\n                        busy.ejectCard();\n                        sessions.incrementAndGet();\n                    } catch (IllegalStateException e) {\n                        rejected.incrementAndGet();\n                    }\n                }\n            });\n            ts[t].start();\n        }\n        for (Thread t : ts) t.join();\n        busy.ejectCard();\n        long cashOut = 100_000 - shared.totalCash();\n        long debited = 1_000_000 - sharedBank.balance(\"rich\");\n        check(cashOut == debited, \"cash dispensed always equals money debited under contention\");\n        check(shared.totalCash() >= 0, \"cash never goes negative\");\n    }\n}\n",
    "output": "PASS: no actions before a card is inserted\nPASS: cannot enter PIN with no card\nPASS: no balance before PIN\nPASS: second customer cannot start a session\nPASS: wrong PIN reported\nPASS: right PIN authenticates and shows balance\nPASS: withdraw dispenses notes and debits account\nPASS: amount not a multiple of smallest note rejected\nPASS: negative amount rejected\nPASS: eject returns to idle\nPASS: no actions after eject\nPASS: insufficient funds rejected\nPASS: failed withdrawal leaves cash and balance unchanged\nPASS: refuses when ATM lacks the notes\nPASS: refusal changes nothing\nPASS: backtracks past a greedy dead end (3 x 200, not 500 + ?)\nPASS: newly loaded denomination is used without code changes\nPASS: deposit credits the account\nPASS: non-positive deposit rejected\nPASS: three wrong PINs block the card\nPASS: blocked card ends the session\nPASS: blocked card cannot start a new session\nPASS: cash dispensed always equals money debited under contention\nPASS: cash never goes negative\n"
