          "file": "Profile.java",
          "body": "import java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.LinkedHashSet;\nimport java.util.List;\nimport java.util.Set;\n\n/** Immutable once built. The Builder lets callers set only the parts they have, and validates at build(). */\npublic class Profile {\n    private final String headline;\n    private final List<Experience> experience;\n    private final Set<String> skills;\n\n    private Profile(Builder b) {\n        this.headline = b.headline;\n        this.experience = Collections.unmodifiableList(new ArrayList<>(b.experience));\n        this.skills = Collections.unmodifiableSet(new LinkedHashSet<>(b.skills));\n    }\n\n    public String headline() { return headline; }\n\n    public List<Experience> experience() { return experience; }\n\n    public Set<String> skills() { return skills; }\n\n    public static Builder builder() {\n        return new Builder();\n    }\n\n    public static class Builder {\n        private String headline;\n        private final List<Experience> experience = new ArrayList<>();\n        private final Set<String> skills = new LinkedHashSet<>();\n\n        public Builder headline(String headline) {\n            this.headline = headline;\n            return this;\n        }\n\n        public Builder experience(Experience e) {\n            experience.add(e);\n            return this;\n        }\n\n        public Builder skill(String skill) {\n            skills.add(skill.trim().toLowerCase());\n            return this;\n        }\n\n        public Profile build() {\n            if (headline == null || headline.isBlank()) throw new IllegalStateException(\"A profile needs a headline\");\n            return new Profile(this);\n        }\n    }\n}\n"
