          "file": "JobBoard.java",
          "body": "import java.util.HashMap;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.NoSuchElementException;\nimport java.util.Set;\n\npublic class JobBoard {\n    private final EventBus events;\n    private final Map<Long, JobPosting> jobs = new HashMap<>();\n    private final Set<String> applied = new HashSet<>(); // \"jobId:memberId\"\n    private long nextId = 1;\n\n    public JobBoard(EventBus events) {\n        this.events = events;\n    }\n\n    public synchronized JobPosting post(Member recruiter, String title, String company) {\n        if (recruiter.role() != Role.RECRUITER) throw new IllegalStateException(\"Only recruiters can post jobs\");\n        JobPosting job = new JobPosting(nextId++, recruiter, title, company);\n        jobs.put(job.id(), job);\n        return job;\n    }\n\n    /**\n     * The duplicate check and the insert are one atomic step: Set.add returns false if the pair was\n     * already there, so a double-click (or two threads) can never create two applications.\n     */\n    public Application apply(Member member, long jobId, String note) {\n        Application application;\n        synchronized (this) {\n            JobPosting job = find(jobId);\n            if (!job.isOpen()) throw new IllegalStateException(\"This job is closed\");\n            if (member.equals(job.poster())) throw new IllegalStateException(\"You cannot apply to your own posting\");\n            if (!applied.add(jobId + \":\" + member.id())) throw new IllegalStateException(\"Already applied\");\n            application = new Application(job, member, note);\n            job.add(application);\n        }\n        events.publish(new JobApplicationReceived(application)); // outside the lock: listeners may be slow\n        return application;\n    }\n\n    public synchronized List<Application> applicationsFor(Member recruiter, long jobId) {\n        JobPosting job = find(jobId);\n        if (!job.poster().equals(recruiter)) throw new IllegalStateException(\"Only the posting recruiter can view applications\");\n        return job.applications();\n    }\n\n    public synchronized void close(Member recruiter, long jobId) {\n        JobPosting job = find(jobId);\n        if (!job.poster().equals(recruiter)) throw new IllegalStateException(\"Only the posting recruiter can close a job\");\n        job.close();\n    }\n\n    private JobPosting find(long id) {\n        JobPosting job = jobs.get(id);\n        if (job == null) throw new NoSuchElementException(\"No job \" + id);\n        return job;\n    }\n}\n"
