          "file": "InAppNotifier.java",
          "body": "import java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/** One notification channel: keeps an in-app inbox per member. An email or push channel is another listener. */\npublic class InAppNotifier implements NotificationListener {\n    private final Map<Member, List<String>> inbox = new HashMap<>();\n\n    @Override\n    public synchronized void handle(DomainEvent event) {\n        if (event instanceof ConnectionRequested e) {\n            add(e.request().to(), e.request().from() + \" wants to connect\");\n        } else if (event instanceof ConnectionAccepted e) {\n            add(e.sender(), e.acceptor() + \" accepted your connection request\");\n        } else if (event instanceof JobApplicationReceived e) {\n            add(e.application().job().poster(), e.application().applicant() + \" applied to \" + e.application().job().title());\n        }\n    }\n\n    private void add(Member to, String message) {\n        inbox.computeIfAbsent(to, m -> new ArrayList<>()).add(message);\n    }\n\n    public synchronized List<String> inboxOf(Member member) {\n        return Collections.unmodifiableList(new ArrayList<>(inbox.getOrDefault(member, List.of())));\n    }\n}\n"
