      "file": "Post.java",
      "body": "import java.time.Instant;\nimport java.util.Set;\nimport java.util.concurrent.ConcurrentHashMap;\n\npublic class Post {\n    private final long id;\n    private final Member author;\n    private final String text;\n    private final Instant createdAt;\n    private final Set<Member> likes = ConcurrentHashMap.newKeySet();\n\n    Post(long id, Member author, String text, Instant createdAt) {\n        this.id = id;\n        this.author = author;\n        this.text = text;\n        this.createdAt = createdAt;\n    }\n\n    public long id() { return id; }\n\n    public Member author() { return author; }\n\n    public String text() { return text; }\n\n    public Instant createdAt() { return createdAt; }\n\n    public boolean like(Member member) {\n        return likes.add(member);\n    }\n\n    public int likeCount() { return likes.size(); }\n\n    @Override\n    public String toString() {\n        return author + \": \\\"\" + text + \"\\\" (\" + likes.size() + \" likes)\";\n    }\n}\n"
