      "body": "import java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\n\npublic class JobPosting {\n    private final long id;\n    private final Member poster;\n    private final String title;\n    private final String company;\n    private final List<Application> applications = new ArrayList<>();\n    private boolean open = true;\n\n    JobPosting(long id, Member poster, String title, String company) {\n        this.id = id;\n        this.poster = poster;\n        this.title = title;\n        this.company = company;\n    }\n\n    public long id() { return id; }\n\n    public Member poster() { return poster; }\n\n    public String title() { return title; }\n\n    public String company() { return company; }\n\n    public boolean isOpen() { return open; }\n\n    void close() { open = false; }\n\n    void add(Application application) { applications.add(application); }\n\n    List<Application> applications() { return Collections.unmodifiableList(new ArrayList<>(applications)); }\n}\n"
